typedef enum {
    ASSET_CHAR_WALK_LEFT_0 = 0,
    ASSET_CHAR_WALK_LEFT_1,
    ASSET_CHAR_WALK_LEFT_2,
    ASSET_CHAR_WALK_RIGHT_0,
    ASSET_CHAR_WALK_RIGHT_1,
    ASSET_CHAR_WALK_RIGHT_2,
