    ASSET_CHAR_WALK_UP_1,
    ASSET_CHAR_WALK_UP_2,
    ASSET_CHAR_DEAD_0,
    ASSET_CHAR_DEAD_1,
    ASSET_CHAR_DEAD_2,
    ASSET_CHAR_DEAD_3,
    ASSET_CHAR_DEAD_4,
    ASSET_CHAR_DEAD_5,
    ASSET_CHAR_DEAD_6,
