#include "bomberman_audio.h"

static const rp_note_t melody_notes[] = {
    {{262, 330, 392}, 0, 4},
    {{294, 370, 440}, 0, 4},
    {{330, 392, 494}, 0, 4},
    {{262, 330, 392}, 0, 4}
};

static const rp_pattern_t melody_patterns[] = {
    {melody_notes, 4}
};

static const uint8_t melody_order[] = {0};

static const rp_song_t bomberman_song = {
    melody_patterns,
    1,
    melody_order,
    1,
    120,
    1
};

static unsigned audio_ms;

void bomberman_audio_init(void) {
    riscplay_audio_init();
    riscplay_audio_all_off();
    riscplay_audio_set_volume(RP_PULSE1, 8);
    riscplay_audio_set_volume(RP_PULSE2, 6);
    riscplay_audio_set_volume(RP_TRIANGLE, 7);
    riscplay_audio_play_song(&bomberman_song);
    audio_ms = 0;
}

void bomberman_audio_tick(void) {
    audio_ms = 16;
    riscplay_audio_update_ms(audio_ms);
}

void bomberman_audio_walk(void) {
    riscplay_audio_sfx_tone(110, 35, 3);
}

